/* Design prototype only: no API calls, microphone access or persistent changes. */
const $ = (id) => document.getElementById(id);
const app = $('app'), thread = $('thread'), dialog = $('dialog');
let state = 'chat', language = 'fr', theme = 'light', currentMode = 'Sohbet', listening = false;
let notes = ['Günlük konuşma örnekleriyle çalışmayı seviyor.', 'Fransızca geçmiş zamanları tekrar etmek istiyor.'];
let remembering = true;
const names = { fr: 'Fransızca', en: 'İngilizce', es: 'İspanyolca' };
const example = { fr: ['la maison', 'La maison est petite.', 'Ev küçük.'], en: ['remember', 'I remember this word.', 'Bu kelimeyi hatırlıyorum.'], es: ['la casa', 'La casa es pequeña.', 'Ev küçük.'] };
const esc = (s) => s.replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const smallIcon = (name) => ({ memory: '<path d="M9 4c-3-1-5 2-4 4-3 1-3 5-1 6-1 3 1 6 4 5 1 3 4 2 4 0V6c0-2-2-3-3-2m6 0c3-1 5 2 4 4 3 1 3 5 1 6 1 3-1 6-4 5-1 3-4 2-4 0V6c0-2 2-3 3-2"/>', trash: '<path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/>', chat: '<path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-6 3V6a2 2 0 0 1 2-2Z"/>', quiz:'<path d="m5 12 4 4L19 6M5 21h14"/>', role:'<path d="M5 4h10v10H8l-4 3V5M17 8h3v10h-4l-3 3v-4"/>', error:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6m0 3v.1"/>', mic:'<rect x="9" y="3" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3"/>', usage:'<path d="M5 20v-6h3v6M11 20V9h3v11M17 20V4h3v16"/>' })[name] || '';
const ico = (name) => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${smallIcon(name)}</svg>`;
function syncDialogTheme() { dialog.dataset.theme = theme; dialog.dataset.lang = language; }
function showDialog(title, content) { $('dialog-title').textContent = title; $('dialog-body').innerHTML = content; syncDialogTheme(); if (!dialog.open) dialog.showModal(); }
$('dialog-close').onclick = () => dialog.close();
dialog.addEventListener('click', e => { if (e.target === dialog) { const box = dialog.getBoundingClientRect(); if (e.clientX < box.x || e.clientX > box.right || e.clientY < box.y || e.clientY > box.bottom) dialog.close(); } });
function row(icon, title, desc, action, selected = false) { return `<button class="action-row${selected ? ' selected' : ''}" data-action="${action}">${ico(icon)}<span class="row-content">${title}${desc ? `<small>${desc}</small>` : ''}</span></button>`; }
function suggestions(labels) { $('suggestions').innerHTML = labels.map(s => `<button class="suggestion" type="button">${s}</button>`).join(''); $('suggestions').querySelectorAll('button').forEach(b => b.onclick = () => { $('message').value = b.textContent; updateSend(); $('message').focus(); }); }
function message(role, body) { return `<article class="message ${role === 'user' ? 'user' : ''}">${role === 'assistant' ? '<div class="speaker">Monki</div>' : ''}<div class="bubble">${body}</div></article>`; }
function render() {
 $('context').hidden = false; $('composer-wrap').hidden = false; $('message').disabled=false; $('mic').disabled=false; $('mode-label').textContent = currentMode; $('subtitle').textContent = `${names[language]} çalışma arkadaşın`;
 $('context-label').textContent = currentMode === 'Rol yap' ? 'Bir sahne seç' : 'Kendi hızında';
 $('recording').hidden = !listening; $('mic').setAttribute('aria-pressed', String(listening));
 const [word,sentence,meaning] = example[language];
 if (state === 'setup') { $('context').hidden=true; $('composer-wrap').hidden=true; thread.innerHTML='<div class="welcome"><img src="assets/monki-wave.webp" alt=""><h2>Birlikte çalışalım.</h2><p>Monki ile konuşmak için Ayarlar → YZ yardımcısı bölümünden kendi Anthropic anahtarını ekleyebilirsin.</p><button class="primary" id="setup-settings">Ayarlara git</button></div>'; suggestions([]); $('setup-settings').onclick=()=>showDialog('Ayarlar bağlantısı','<p>Üretim uygulamasında mevcut YZ ayarları açılır. Bu tasarım prototipinde bağlantı gösterim amaçlıdır.</p>'); } else if (state === 'welcome') { thread.innerHTML = `<div class="welcome"><img src="assets/monki-wave.webp" alt=""><h2>Nereden başlayalım?</h2><p>Bir kelime, bir kural ya da aklındaki bir cümle. Birlikte çalışabiliriz.</p><button class="suggestion" id="start">Bana kısa bir diyalog yaz</button></div>`; suggestions([]); $('start').onclick = () => { $('message').value = 'Bana kısa bir diyalog yaz'; updateSend(); $('message').focus(); }; }
 else if (state === 'roleplay') { const scenes = [['cafe','Kafede sipariş'],['hotel','Otelde giriş'],['directions','Yol sormak'],['doctor','Doktorda'],['interview','İş görüşmesi'],['shopping','Alışveriş']]; thread.innerHTML = '<h2 class="scene-heading">Nerede konuşalım?</h2><p class="scene-intro">Bir sahne seç. Monki karşındaki kişi olsun.</p><div class="scene-grid">'+scenes.map(([key,label])=>`<button class="scene" data-scene="${label}"><img src="assets/role-${key}.webp" alt=""><span>${label}</span></button>`).join('')+'</div>'; suggestions([]); thread.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>{ state='scene'; currentMode='Rol yap'; $('context-label').textContent=b.dataset.scene; thread.innerHTML=message('assistant', `<p><strong>${esc(b.dataset.scene)}</strong></p><p>Bu sahnede kısa cümlelerle başlayalım. İlk cümleni yazabilirsin.</p>`); }); }
 else { thread.innerHTML = '<div class="day">BUGÜN</div>'+message('user',language==='fr'?'“Maison” ne demek?':language==='en'?'“Remember” ne demek?':'“Casa” ne demek?')+message('assistant', `<p><strong lang="${language}">${word}</strong> ${language==='en'?'“hatırlamak”':'“ev”'} demek. Bir örneğe bakalım:</p><span class="target" lang="${language}">${sentence}</span><p class="translation">${meaning}</p>`)+message('assistant','Bu kelimeyle kısa bir cümle kurmak ister misin?'); suggestions(['Bir örnek daha','Beni sına']); if (state === 'error') { thread.innerHTML += '<div class="error" role="alert">Yanıt şu an gelmedi. Yazdığın mesaj burada duruyor.<button class="text-btn" id="retry">Yeniden dene</button></div>'; $('retry').onclick=()=>{state='chat';render();}; } }
 if(state==='limit'){thread.insertAdjacentHTML('beforeend','<div class="error" role="status">Günlük soru sınırına ulaştın. Sınırını Ayarlar’dan değiştirebilirsin.</div>');$('message').disabled=true;$('mic').disabled=true;$('send').disabled=true;suggestions([]);}
 document.querySelectorAll('[data-state]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.state===state)));
}
function updateSend() { $('send').disabled = !$('message').value.trim(); }
$('message').oninput = updateSend;
$('message').addEventListener('keydown', e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('composer').requestSubmit();}});
$('composer').onsubmit = e=>{e.preventDefault();const text=$('message').value.trim();if(!text)return;if(state==='welcome'){thread.innerHTML='';}state='chat';thread.insertAdjacentHTML('beforeend',message('user',esc(text))+message('assistant','Birlikte kısa bir örnekle devam edelim. Bu kelimeyle kendi cümleni kurmak ister misin?'));$('message').value='';updateSend();thread.scrollTop=thread.scrollHeight;};
$('mic').onclick=()=>{listening=!listening;$('recording').hidden=!listening;$('mic').setAttribute('aria-pressed',String(listening));};
$('mode').onclick=()=>{const modes=[['chat','Sohbet','Bir kelime, kural veya cümle'],['quiz','Sınav','Her seferinde tek soru'],['role','Rol yap','Gündelik bir sahneyi çalış'],['error','Hatalarım','Son hatalarını birlikte incele'],['mic','Telaffuz','Telaffuz puanı düşük kelimeler'],['chat','Günün sohbeti','Bugünün zayıf kelimeleri']];showDialog('Nasıl çalışalım?',`<div class="action-list">${modes.map(([icon,title,desc])=>row(icon,title,desc,'mode:'+title,currentMode===title)).join('')}</div>`);};
$('more').onclick=()=>showDialog('Monki seçenekleri',`<div class="action-list">${row('memory','Hatırladıkları',`${notes.length} kısa not · kontrol sende`,'memory')}${row('usage','Kullanım','Bu ay 12 soru · yaklaşık $0,024','usage')}${row('trash','Sohbeti temizle','Bu dildeki mesajları kaldır','clear')}</div>`);
function memoryView(){showDialog('Hatırladıkları',`<p class="dialog-note">Sohbetten kalan kısa notlar. İstediğin notu silebilir veya hatırlamayı kapatabilirsin.</p><ul class="memory-list">${notes.map((n,i)=>`<li><span>${esc(n)}</span><button class="icon-btn" aria-label="Notu sil: ${esc(n)}" data-action="forget:${i}">${ico('trash')}</button></li>`).join('')||'<li>Henüz not yok.</li>'}</ul><button class="primary quiet" aria-pressed="${remembering}" data-action="remember">Hatırlama: ${remembering?'açık':'kapalı'}</button>${notes.length?'<button class="text-btn" data-action="forget-all">Tüm notları sil</button>':''}`);}
$('dialog-body').onclick=e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;if(action.startsWith('mode:')){currentMode=action.slice(5);state=currentMode==='Rol yap'?'roleplay':'welcome';dialog.close();render();}else if(action==='memory'){memoryView();}else if(action==='remember'){remembering=!remembering;memoryView();}else if(action.startsWith('forget:')){notes.splice(Number(action.slice(7)),1);memoryView();}else if(action==='forget-all'){notes=[];memoryView();}else if(action==='usage'){showDialog('Monki kullanımı','<p>Bu ay <strong>12 soru</strong></p><p>Yaklaşık maliyet <strong>$0,024</strong></p><p class="dialog-note">Aylık bütçeni ve günlük soru sınırını Ayarlar’dan yönetebilirsin.</p>');}else if(action==='clear'){showDialog('Sohbet temizlensin mi?','<p>Bu dildeki mesajlar kaldırılır. Monki’nin hatırladığı notlar korunur.</p><div class="confirm-actions"><button class="primary quiet" data-action="cancel">Vazgeç</button><button class="primary" data-action="confirm-clear">Temizle</button></div>');}else if(action==='cancel'){dialog.close();}else if(action==='confirm-clear'){state='welcome';dialog.close();render();}};
$('close').onclick=()=>{ $('panel').hidden=true;const closed=document.createElement('div');closed.className='chat-closed';closed.id='closed';closed.innerHTML='<div><p>Monki paneli kapalı.</p><button class="primary" id="reopen">Monki’yi aç</button></div>';app.append(closed);$('reopen').onclick=()=>{closed.remove();$('panel').hidden=false;$('more').focus();};};
document.querySelectorAll('[data-state]').forEach(b=>b.onclick=()=>{state=b.dataset.state;currentMode=state==='roleplay'?'Rol yap':'Sohbet';render();});
$('theme-control').onclick=()=>{theme=theme==='light'?'dark':theme==='dark'?'calm':'light';app.dataset.theme=theme;syncDialogTheme();$('theme-control').textContent=theme==='light'?'Koyu tema':theme==='dark'?'Sakin tema':'Açık tema';};
$('language-control').onclick=()=>{language=language==='fr'?'en':language==='en'?'es':'fr';app.dataset.lang=language;$('language-control').textContent='Dil: '+language.toUpperCase();syncDialogTheme();render();};
const params=new URLSearchParams(location.search);if(params.has('export'))document.body.classList.add('export-view');if(params.has('desktop'))document.body.classList.add('desktop-demo');if(params.has('theme')){theme=params.get('theme');app.dataset.theme=theme;}if(params.has('lang')){language=params.get('lang');if(!names[language])language='fr';app.dataset.lang=language;}if(params.has('state')){state=params.get('state');if(state==='roleplay')currentMode='Rol yap';}render();if(params.get('state')==='modes')$('mode').click();if(params.get('state')==='memory'){$('more').click();memoryView();}if(params.get('state')==='recording')$('mic').click();
